function scoreTone(tone: string) {
  return tone === "amber" ? "bg-amber-50 text-amber-700 border-amber-200" : tone === "green" ? "bg-emerald-50 text-emerald-700 border-emerald-200" : tone === "blue" ? "bg-blue-50 text-blue-700 border-blue-200" : "bg-slate-100 text-slate-700 border-slate-200";
}

function localAssessment(questions: Question[], answers: Record<string, number>): AssessmentResult {
  const subjects = Array.from(new Set(questions.map((question) => question.subject)));
  const stats = subjects.map((subject) => {
    const subjectQuestions = questions.filter((question) => question.subject === subject);
    const correct = subjectQuestions.filter((question) => answers[question.id] === question.correct_index).length;
    const wrong = subjectQuestions.filter((question) => answers[question.id] !== undefined && answers[question.id] !== question.correct_index).length;
    return { subject, score: correct * 20, correct, wrong, blank: subjectQuestions.length - correct - wrong, target: 80 };
  });
  const correct = stats.reduce((sum, item) => sum + item.correct, 0);
  const wrong = stats.reduce((sum, item) => sum + item.wrong, 0);
  const net = Math.round((correct - wrong / 4) * 100) / 100;
  return { ...emptyAssessmentResult, id: `local-${Date.now()}`, score: Math.round(280 + net * 6.8), net, subjects: stats, strengths: stats.filter((item) => item.correct > 0).slice(0, 2).map((item) => item.subject), gaps: stats.filter((item) => item.wrong > 0).slice(0, 2).map((item) => item.subject), percentile: `%${Math.max(2, 48 - Math.round(net * 4))}`, message: "Sonuçların seviyeni iyi gösteriyor. Önce en hızlı net kazanacağın konuyu kapatıp güçlü olduğun ritmi koruyacağız." };
}

function MetricCard({ label, value, change, tone }: { label: string; value: string; change: string; tone: string }) {
  return <Card className="metric-card border-slate-200/80 bg-white/85 shadow-sm" data-testid={`metric-card-${label.toLowerCase().replaceAll(" ", "-")}`}><CardContent className="p-5"><div className="mb-4 flex items-center justify-between"><span className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-500" data-testid={`metric-label-${label.toLowerCase().replaceAll(" ", "-")}`}>{label}</span><Activity className="size-4 text-slate-400" /></div><div className="flex items-end justify-between gap-2"><strong className="font-heading text-2xl font-bold tracking-tight text-slate-900" data-testid={`metric-value-${label.toLowerCase().replaceAll(" ", "-")}`}>{value}</strong><Badge className={scoreTone(tone)} data-testid={`metric-change-${label.toLowerCase().replaceAll(" ", "-")}`}>{change}</Badge></div></CardContent></Card>;
}

